/**
 * Shared Mathematical Vectors Cross-Check
 * 
 * Verifies that the TypeScript implementation in web/src/lib/geometry.ts
 * is 100% mathematically identical to the Python core pipeline implementation.
 * 
 * Vectors generated by tests/test_vectors.py.
 * If TypeScript and Python disagree on any vector, the test and build fail.
 */

import { describe, it, expect } from 'vitest';
import vectorsData from './fixtures/vectors.json';
import {
  elevationAngleDeg,
  discFractionFlat,
  horizonDipDeg,
} from '../lib/geometry';

describe('Shared Vector Verification (TypeScript vs Python Core)', () => {
  it('validates elevationAngleDeg across all distance and height vectors', () => {
    expect(vectorsData.elevation_vectors.length).toBeGreaterThan(0);

    for (const v of vectorsData.elevation_vectors) {
      const computed = elevationAngleDeg(
        v.dist_m,
        v.feature_height_m,
        v.observer_height_m
      );

      // Require extreme numerical precision (< 1e-9 degrees)
      expect(Math.abs(computed - v.expected_el_deg)).toBeLessThan(1e-9);
    }
  });

  it('validates Prompt 14 default: 100m ridge at 10km gives ~0.408° (about 0.41°)', () => {
    const el = elevationAngleDeg(10000.0, 100.0, 0.0);
    expect(Math.abs(el - 0.408031)).toBeLessThan(1e-4);
    expect(Number(el.toFixed(2))).toBe(0.41);
  });

  it('validates discFractionFlat across all clipping and ratio vectors', () => {
    expect(vectorsData.disc_vectors.length).toBeGreaterThan(0);

    for (const v of vectorsData.disc_vectors) {
      const computed = discFractionFlat(v.e_deg, v.r_deg);

      // Exact numerical match (< 1e-9)
      expect(Math.abs(computed - v.expected_fraction)).toBeLessThan(1e-9);
    }
  });

  it('validates horizonDipDeg across all mast heights', () => {
    expect(vectorsData.dip_vectors.length).toBeGreaterThan(0);

    for (const v of vectorsData.dip_vectors) {
      const computed = horizonDipDeg(v.observer_height_m);

      expect(Math.abs(computed - v.expected_dip_deg)).toBeLessThan(1e-9);
    }

    // Dip for h=2m observer is -0.086937°
    const dip2m = horizonDipDeg(2.0);
    expect(Math.abs(dip2m - (-0.086937))).toBeLessThan(1e-5);
  });
});
